UPDATE `communicationtemplate` SET `Text`='<p>Dear [#]FirstName[/#] [#]LastName[/#],</p><p>You have successfully signed in to your online banking profile.</p><p>Regards,<br />Infinity Bank</p>.' WHERE `id`='76';
UPDATE `communicationtemplate` SET `Text`='<p>Dear [#]FirstName[/#] [#]LastName[/#],</p><p>You have made an invalid sign in attempt for your username [#]MaskedUsername[/#]  on [#]ServerDate[/#] [#]ServerTime[/#].</p><p>Regards,<br />Infinity Bank</p><p>&nbsp;</p>' WHERE `id`='80';
UPDATE `emailtemplates` SET `TemplateText`='<p>&nbsp;</p><center><div style="width: 95%; height: 5px; margin: 0px 0px 0px 0px;"><div><table border="0" width="100%" cellspacing="0" cellpadding="0"><tbody><tr><td style="background-color: #284e77; font-size: 1px; line-height: 1px; -webkit-text-size-adjust: none;" align="center" valign="top" bgcolor="#284e77" height="10">&nbsp;</td></tr></tbody></table></div></div><div style="width: 95%; margin: 0px 0px 50px 0px;"><div style="display: inline-block; text-align: left;"><table style="width: 50%;" width="50%"><tbody><tr><td width="200"><img style="text-align: right; width: 200px; border: 0;" src="https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png" alt="temenos_logo" width="200" /></td></tr></tbody></table> <br /><br />Hi %firstName% %lastName%,<br /><br />You are enrolled to Digital Banking Channel. Please activate your account now.<br /><br />%userName% is your username. Activation code is sent to you registered mobile number.<br /><br />You are required to input your username &amp; activation code in the link below.<br /><br /><div style="text-align: center; border-width: 1px; border-radius: 4px;"><table style="table-layout: fixed;" border="0" width="100%" cellspacing="0" cellpadding="0"><tbody><tr><td style="color: #ffffff; background-color: #333b44; word-wrap: break-word; word-break: break-all; padding: 10px; line-height: 20px;" align="center"><div style="margin: 10px 10px 10px 10px; font-size: 13px;">To activate your account and set a password,<a style="color: #11abeb;" href="%resetPasswordLink%">click here</a> <br />or paste the following link on your browser: <br /><br /><a style="color: #11abeb;">%resetPasswordLink%</a></div></td></tr></tbody></table></div> <br /><center>The activation code will expire in %activationCodeExpiry% days , so activate it right away.</center><br /><br />Regards,<br />Temenos Banking Team <br /><br /><br /><br /><span style="color: #999999; font-size: 12px;">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos, Inc. www.temenos.com </span><br /><br /><div align="center"><span style="color: #999999;"><strong>(c) Copyright Temenos Digital Retail Origination</strong>. All rights reserved.</span></div></div></div></center>' WHERE `id`='22';
UPDATE `configurations` SET `config_value` = 'BOTH' WHERE (`configuration_id` = '131');
