INSERT INTO `configurations` (`configuration_id`,`bundle_id`,`config_type`,`config_key`,`description`,`config_value`,`target`,`isPreLoginConfiguration`) VALUES ('7a128ba1-8faa-468c-a782-4ea013a92044','NUO_CONFIG_BUNDLE','PREFERENCE','INCOMEDOCUMENT_CONFIG','IncomeDocument','{\"UserActionName\": \"IncomeDocument\",\"Group\": \"Income\",\"Skippable\": \"true\",\"Title\": \"Income document\",\"UserActionType\": \"DocumentUpload\",\"Options\": \"\",\"OptionsType\": \"\",\"Description\": \"Upload a document showing your income - such as a payslip or tax statement. This will help us process your application faster.\",\"DynamicDataDefinition\": \"\",\"NeedsReview\": \"true\"}','CLIENT','1');
INSERT INTO `configurations` (`configuration_id`,`bundle_id`,`config_type`,`config_key`,`description`,`config_value`,`target`,`isPreLoginConfiguration`) VALUES ('7a128ba1-8faa-468c-a782-4ea013a92045','NUO_CONFIG_BUNDLE','PREFERENCE','MOBILEPHONENUMBERCONSENT_CONFIG','MobilePhoneNumberConsent','{\"UserActionName\": \"MobilePhoneNumberConsent\",\"Group\": \"Legal\",\"Skippable\": \"false\",\"Title\": \"Mobile phone number consent\",\"UserActionType\": \"Radio-ButtonSelection\",\"Options\": [\"The bank can call or text me through automated means\",\"The bank can only contact me through non-automated means\",\"The bank can\'t contact me (this may impact your approval)\"],\"OptionsType\": \"PREDEFINED\",\"Description\": \"If the phone number provided on this application is a mobile phone number, it is my mobile phone number, and by clicking on the button below, I consent to receive auto-dialed and prerecorded/artificial calls, including texts, relating to my relationship with this bank. It may include handling, servicing, and billing for any of my account(s). Message and data rates may apply. You can stop these messages by contacting our service center.\",\"DynamicDataDefinition\": \"\",\"NeedsReview\": \"true\"}','CLIENT', '1');
